<?php
require_once __DIR__ . '/../bootstrap.php'; require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method Not Allowed');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$allowed=['pending','processing','completed','cancelled'];if(!$id||!in_array($status,$allowed,true)){set_flash('error','Mã đơn hàng hoặc trạng thái không hợp lệ.');header('Location: '.admin_url('orders/index.php'));exit;}try{$st=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$st->execute([$status,$id]);set_flash($st->rowCount()?'success':'warning',$st->rowCount()?'Đã cập nhật trạng thái đơn hàng.':'Trạng thái không thay đổi hoặc đơn hàng không tồn tại.');}catch(PDOException $e){set_flash('error','Không thể cập nhật trạng thái đơn hàng.');}header('Location: '.admin_url('orders/detail.php?id='.$id));exit;
